package com.customrpg.managers;

import com.customrpg.CustomRPG;
import com.customrpg.players.PlayerTalents;
import com.customrpg.talents.*;
import com.customrpg.utils.SkillDamageGuard;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.entity.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.*;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.plugin.PluginManager;
import org.bukkit.util.BoundingBox;
import org.bukkit.util.Vector;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class NecroTalentSkillsTest {
    CustomRPG plugin;World world;Player player;TalentManager manager;ExpandedTalentSkills combat;NecroTalentSkills skills;PlayerTalents learned;PluginManager events;
    final List<Skeleton> bodies=new ArrayList<>();final Map<Skeleton,AtomicReference<Location>> positions=new HashMap<>();double absorption;boolean rejectSpawn,rejectTransfer;
    final List<Entity> nearby=new ArrayList<>();final Map<UUID,Double> health=new HashMap<>(),speed=new HashMap<>();final Map<String,Talent> definitions=new HashMap<>();
    @BeforeEach void setup(){
        plugin=mock(CustomRPG.class);var server=mock(Server.class);events=mock(PluginManager.class);when(plugin.getServer()).thenReturn(server);when(server.getPluginManager()).thenReturn(events);when(plugin.getLogger()).thenReturn(java.util.logging.Logger.getAnonymousLogger());
        world=mock(World.class);when(world.isChunkLoaded(anyInt(),anyInt())).thenReturn(true);when(world.getMinHeight()).thenReturn(-64);when(world.getMaxHeight()).thenReturn(320);var border=mock(WorldBorder.class);when(world.getWorldBorder()).thenReturn(border);when(border.isInside(any())).thenReturn(true);
        player=mock(Player.class);when(player.getUniqueId()).thenReturn(UUID.randomUUID());when(player.getWorld()).thenReturn(world);when(player.isOnline()).thenReturn(true);when(player.isValid()).thenReturn(true);when(player.getGameMode()).thenReturn(GameMode.SURVIVAL);when(player.getLocation()).thenAnswer(i->new Location(world,0,64,0));when(player.getEyeLocation()).thenAnswer(i->new Location(world,0,65.5,0));when(player.getEyeHeight()).thenReturn(1.5);when(player.hasLineOfSight(any(Entity.class))).thenReturn(true);
        learned=new PlayerTalents();manager=mock(TalentManager.class);when(plugin.getTalentManager()).thenReturn(manager);when(manager.getPlayerTalents(player)).thenReturn(learned);when(manager.findTalent(anyString())).thenAnswer(i->definitions.get(i.getArgument(0)));
        combat=spy(new ExpandedTalentSkills(plugin,()->0,mock(ExpandedTalentSkills.StatusEffects.class)));var motion=mock(NecroTalentSkills.Motion.class);doAnswer(i->{LivingEntity e=i.getArgument(0);speed.put(e.getUniqueId(),i.getArgument(1));return null;}).when(motion).set(any(),anyDouble());doAnswer(i->{LivingEntity e=i.getArgument(0);speed.remove(e.getUniqueId());return null;}).when(motion).clear(any());skills=new NecroTalentSkills(plugin,combat,motion,(owner,at,kind)->spawn(at,kind),new EarthShields.Access(){public double amount(Player p){return absorption;}public void amount(Player p,double n){absorption=n;}public void capacity(Player p,double n){}},(target,n,attacker)->{if(!rejectTransfer)health.compute(target.getUniqueId(),(id,hp)->Math.max(0,hp-n));});
        when(world.getNearbyEntities(any(Location.class),anyDouble(),anyDouble(),anyDouble())).thenAnswer(i->new ArrayList<>(nearby));when(world.getBlockAt(anyInt(),anyInt(),anyInt())).thenAnswer(i->{int x=i.getArgument(0),y=i.getArgument(1),z=i.getArgument(2);var b=mock(Block.class);when(b.isPassable()).thenReturn(y>63);when(b.getBoundingBox()).thenReturn(new BoundingBox(x,y,z,x+1,y+1,z+1));return b;});when(world.getBlockAt(any(Location.class))).thenAnswer(i->{Location at=i.getArgument(0);return world.getBlockAt(at.getBlockX(),at.getBlockY(),at.getBlockZ());});
    }
    LivingEntity mob(double x,double z){var e=mock(Zombie.class);when(e.getUniqueId()).thenReturn(UUID.randomUUID());when(e.getWorld()).thenReturn(world);when(e.isValid()).thenReturn(true);when(e.getMaxHealth()).thenReturn(1000.0);when(e.getLocation()).thenAnswer(i->new Location(world,x,64,z));when(e.getEyeLocation()).thenAnswer(i->new Location(world,x,65.5,z));when(e.getPersistentDataContainer()).thenReturn(mock(PersistentDataContainer.class));health.put(e.getUniqueId(),1000.0);when(e.getHealth()).thenAnswer(i->health.get(e.getUniqueId()));when(e.isDead()).thenAnswer(i->health.get(e.getUniqueId())<=0);doAnswer(i->{health.compute(e.getUniqueId(),(id,hp)->Math.max(0,hp-(double)i.getArgument(0)));return null;}).when(e).damage(anyDouble(),eq(player));nearby.add(e);return e;}
    Talent talent(NecroSkill s){var t=new Talent(s.id,s.title,"test",TalentType.ACTIVE,TalentBranch.NECROMANCER,3,1,List.of(),Talent.PrerequisiteMode.ALL,s.slot,"WITHER_ROSE","凋零玫瑰",s.cooldown,s.mana,0,"RIGHT_CLICK");var d=new Talent.TalentLevelData();d.addEffect("baseDamage",s.damage);d.addEffect("range",s.range);t.addLevelData(1,d);definitions.put(s.id,t);learned.setTalentLevel(s.id,1);if(s==NecroSkill.GATE)learned.setUltimateSkill(s.id);else if(!Arrays.asList(learned.getSelectedSkills()).contains(s.id)){int i=0;while(i<4&&learned.getSelectedSkills()[i]!=null)i++;learned.setSelectedSkill(i,s.id);}return t;}
    void aim(LivingEntity target){for(int range:new int[]{10,11,12})doReturn(target).when(combat).aim(player,range);}
    void ticks(int n){for(int i=0;i<n;i++)skills.tick();}
    EntityDamageByEntityEvent attack(LivingEntity attacker,double n){var e=mock(EntityDamageByEntityEvent.class);when(e.getEntity()).thenReturn(player);when(e.getDamager()).thenReturn(attacker);var value=new AtomicReference<>(n);when(e.getDamage()).thenAnswer(i->value.get());when(e.getFinalDamage()).thenAnswer(i->value.get());doAnswer(i->{value.set(i.getArgument(0));return null;}).when(e).setDamage(anyDouble());return e;}
    Skeleton spawn(Location at,NecroRoster.Kind kind){
        if(rejectSpawn)return null;var e=mock(Skeleton.class);UUID id=UUID.randomUUID();when(e.getUniqueId()).thenReturn(id);when(e.getWorld()).thenReturn(world);var location=new AtomicReference<>(at.clone());positions.put(e,location);when(e.getLocation()).thenAnswer(x->location.get().clone());when(e.getEyeLocation()).thenAnswer(x->location.get().clone().add(0,1.5,0));var valid=new AtomicBoolean(true);when(e.isValid()).thenAnswer(x->valid.get());when(e.isDead()).thenAnswer(x->health.get(id)<=0);when(e.getPersistentDataContainer()).thenReturn(mock(PersistentDataContainer.class));health.put(id,(double)kind.hp);when(e.getHealth()).thenAnswer(x->health.get(id));when(e.getMaxHealth()).thenReturn((double)kind.hp);doAnswer(x->{valid.set(false);return null;}).when(e).remove();when(e.teleport(any(Location.class))).thenAnswer(x->{location.set(((Location)x.getArgument(0)).clone());return true;});bodies.add(e);return e;
    }
    long alive(){return bodies.stream().filter(Entity::isValid).count();}
    EntityDamageByEntityEvent incoming(Entity victim,Entity from,double n){var e=attack(from instanceof LivingEntity l?l:player,n);when(e.getEntity()).thenReturn(victim);when(e.getDamager()).thenReturn(from);return e;}
    @Test void summonReplacesTwoBodiesAndEachHasFourAttacksAtFortyTickIntervals(){var target=mob(0,.5);var t=talent(NecroSkill.SUMMON);assertTrue(skills.cast(player,t,1));assertEquals(2,alive());ticks(39);verify(target,never()).damage(anyDouble(),eq(player));ticks(1);verify(target,times(2)).damage(2,player);ticks(39);verify(target,times(2)).damage(2,player);ticks(121);verify(target,times(8)).damage(2,player);assertTrue(skills.cast(player,t,1));assertEquals(2,alive());verify(bodies.get(0)).remove();ticks(241);assertEquals(0,alive());}
    @Test void rejectedReplacementPreservesExistingSquadAndResourcesAreNotCommitted(){var t=talent(NecroSkill.SUMMON);skills.cast(player,t,1);rejectSpawn=true;assertFalse(skills.cast(player,t,1));assertEquals(2,alive());verify(bodies.get(0),never()).remove();}
    @Test void commandWorksWithoutMinionsAndEnhancesExactlyTwoAttacksPerUnit(){var target=mob(0,.5);aim(target);var cmd=talent(NecroSkill.COMMAND);assertTrue(skills.cast(player,cmd,1));verify(target).damage(3,player);skills.cast(player,talent(NecroSkill.SUMMON),1);skills.cast(player,cmd,1);clearInvocations(target);ticks(165);verify(target,times(4)).damage(3,player);verify(target,times(4)).damage(2,player);}
    @Test void sacrificeConsumesOneNormalImmediatelyAndOnlyDamagesAtTickEleven(){var target=mob(0,.5);assertFalse(skills.cast(player,talent(NecroSkill.SACRIFICE),1));skills.cast(player,talent(NecroSkill.SUMMON),1);assertTrue(skills.cast(player,talent(NecroSkill.SACRIFICE),1));assertEquals(1,alive());ticks(10);verify(target,never()).damage(anyDouble(),eq(player));ticks(1);verify(target,times(1)).damage(9,player);assertEquals(.25,speed.get(target.getUniqueId()));}
    @Test void fusionRequiresTwoNormalsBlocksSummoningAndCannotBeSacrificed(){var f=talent(NecroSkill.COLOSSUS);assertFalse(skills.cast(player,f,1));var summon=talent(NecroSkill.SUMMON);skills.cast(player,summon,1);assertTrue(skills.cast(player,f,1));assertEquals(1,alive());assertEquals(20,bodies.get(2).getHealth());assertFalse(skills.cast(player,summon,1));assertFalse(skills.cast(player,talent(NecroSkill.SACRIFICE),1));ticks(161);assertEquals(0,alive());}
    @Test void giantGuardMeasuresAcceptedHpLossAndCanAbsorbOnlySixOnce(){var enemy=mob(0,2);skills.cast(player,talent(NecroSkill.SUMMON),1);skills.cast(player,talent(NecroSkill.COLOSSUS),1);var giant=bodies.get(2);rejectTransfer=true;var blocked=attack(enemy,20);skills.mitigate(blocked);assertEquals(20,blocked.getDamage());rejectTransfer=false;var accepted=attack(enemy,20);skills.mitigate(accepted);assertEquals(14,accepted.getDamage(),1e-8);assertEquals(14,giant.getHealth());var later=attack(enemy,20);skills.mitigate(later);assertEquals(20,later.getDamage());}
    @Test void lanternGrantsExactlyFiveAndReducesMinionDamageFortyPercentUntilExpiry(){skills.cast(player,talent(NecroSkill.SUMMON),1);var lantern=talent(NecroSkill.LANTERN);skills.cast(player,lantern,1);skills.cast(player,lantern,1);assertEquals(5,absorption);var enemy=mob(0,2);var hit=incoming(bodies.get(0),enemy,10);skills.mitigate(hit);assertEquals(6,hit.getDamage());ticks(100);var after=incoming(bodies.get(0),enemy,10);skills.mitigate(after);assertEquals(10,after.getDamage());assertEquals(0,absorption);}
    @Test void prisonRootAndPostRootSlowFollowSeparateWindows(){var target=mob(0,6);aim(target);skills.cast(player,talent(NecroSkill.PRISON),1);assertEquals(1,speed.get(target.getUniqueId()));ticks(24);assertEquals(.25,speed.get(target.getUniqueId()));ticks(40);assertEquals(0,speed.get(target.getUniqueId()));}
    @Test void gateLocksAtThirtyThenDealsThreeDistinctWavesAndReplacesTheSquadWithKnights(){var target=mob(0,6);skills.cast(player,talent(NecroSkill.SUMMON),1);skills.cast(player,talent(NecroSkill.GATE),1);ticks(42);verify(target,never()).damage(4,player);verify(target,never()).damage(6,player);ticks(1);verify(target).damage(4,player);ticks(10);verify(target,times(2)).damage(4,player);ticks(10);verify(target).damage(6,player);ticks(8);assertEquals(4,bodies.size());assertEquals(2,alive());assertEquals(14,bodies.get(2).getHealth());assertFalse(skills.cast(player,talent(NecroSkill.SACRIFICE),1));ticks(161);assertEquals(0,alive());}
    @Test void gateRejectsEnemiesOutsideRectangleAndBehindBlockingWalls(){var beside=mob(5,6);var behind=mob(0,-2);var high=mob(0,15);skills.cast(player,talent(NecroSkill.GATE),1);ticks(70);verify(beside,never()).damage(anyDouble(),eq(player));verify(behind,never()).damage(anyDouble(),eq(player));verify(high,never()).damage(anyDouble(),eq(player));}
    @Test void friendlyOwnerHitsCannotKillOwnBodyAndHostileMinionHitsCannotRecurse(){skills.cast(player,talent(NecroSkill.SUMMON),1);var e=incoming(bodies.get(0),player,20);skills.friendly(e);verify(e).setCancelled(true);var enemy=mob(0,2);var allowed=incoming(bodies.get(0),enemy,2);skills.friendly(allowed);verify(allowed,never()).setCancelled(true);}
    @Test void deathQuitWorldChangeAndShutdownClearBodiesDebuffsAndQueuedDamage(){var target=mob(0,6);aim(target);skills.cast(player,talent(NecroSkill.SUMMON),1);skills.cast(player,talent(NecroSkill.PRISON),1);skills.cast(player,talent(NecroSkill.GATE),1);skills.cancel(player);ticks(80);assertEquals(0,alive());verify(target,never()).damage(6,player);assertEquals(0,speed.get(target.getUniqueId()));skills.cast(player,talent(NecroSkill.SUMMON),1);when(player.getWorld()).thenReturn(mock(World.class));ticks(1);assertEquals(0,alive());skills.shutdown();}
    @Test void lanceTraversesCurrentSegmentsAndHitsOnlyTheFirstTwoBeforeWall(){var first=mob(0,2);var second=mob(0,4);var third=mob(0,6);when(world.rayTraceEntities(any(Location.class),any(Vector.class),anyDouble(),anyDouble(),any())).thenAnswer(i->{Location from=i.getArgument(0);double length=i.getArgument(2);java.util.function.Predicate<Entity> filter=i.getArgument(4);return nearby.stream().filter(filter).filter(e->e.getLocation().getZ()>=from.getZ()&&e.getLocation().getZ()<=from.getZ()+length).findFirst().map(e->new org.bukkit.util.RayTraceResult(e.getLocation().toVector(),e)).orElse(null);});skills.cast(player,talent(NecroSkill.LANCE),1);ticks(5);verify(first,never()).damage(anyDouble(),eq(player));ticks(8);verify(first,times(1)).damage(8,player);verify(second,times(1)).damage(5,player);verify(third,never()).damage(anyDouble(),eq(player));}
    @Test void lanceCannotHitAnEnemyThatMovesBehindTheMissileOrAcrossAWall(){var target=mob(0,4);when(world.rayTraceBlocks(any(Location.class),any(Vector.class),anyDouble(),any(),anyBoolean())).thenAnswer(i->{Location from=i.getArgument(0);return new org.bukkit.util.RayTraceResult(from.toVector().add(new Vector(0,0,.3)),mock(Block.class),org.bukkit.block.BlockFace.NORTH);});skills.cast(player,talent(NecroSkill.LANCE),1);ticks(20);verify(target,never()).damage(anyDouble(),eq(player));}
    @Test void aCancelledRootNeverAppliesControlAndBossesReceiveOnlySlow(){var target=mob(0,6);aim(target);doAnswer(i->{if(i.getArgument(0) instanceof NecroControlEvent e)e.setCancelled(true);return null;}).when(events).callEvent(any());skills.cast(player,talent(NecroSkill.PRISON),1);assertTrue(speed.isEmpty());reset(events);var boss=mock(Warden.class);when(boss.getUniqueId()).thenReturn(UUID.randomUUID());when(boss.getWorld()).thenReturn(world);when(boss.isValid()).thenReturn(true);when(boss.getLocation()).thenReturn(new Location(world,0,64,6));when(boss.getPersistentDataContainer()).thenReturn(mock(PersistentDataContainer.class));var hp=new double[]{100};when(boss.getMaxHealth()).thenReturn(100.0);when(boss.getHealth()).thenAnswer(x->hp[0]);doAnswer(x->{hp[0]-=(double)x.getArgument(0);return null;}).when(boss).damage(anyDouble(),eq(player));aim(boss);skills.cast(player,talent(NecroSkill.PRISON),1);assertEquals(.25,speed.get(boss.getUniqueId()));}
    @Test void pvpMustBeEnabledBeforeAnotherPlayerCanAttackTheSquad(){skills.cast(player,talent(NecroSkill.SUMMON),1);var other=mock(Player.class);when(other.getUniqueId()).thenReturn(UUID.randomUUID());when(other.getWorld()).thenReturn(world);when(other.getLocation()).thenReturn(new Location(world,0,64,2));when(other.isValid()).thenReturn(true);when(other.isOnline()).thenReturn(true);when(other.getGameMode()).thenReturn(GameMode.SURVIVAL);when(other.getPersistentDataContainer()).thenReturn(mock(PersistentDataContainer.class));var blocked=incoming(bodies.get(0),other,5);skills.friendly(blocked);verify(blocked).setCancelled(true);when(world.getPVP()).thenReturn(true);var allowed=incoming(bodies.get(0),other,5);skills.friendly(allowed);verify(allowed,never()).setCancelled(true);}
    @Test void taggedBodiesNeverReceiveMonsterScalingRewardsOrAutomaticHostility(){var e=mock(Skeleton.class);var pdc=mock(PersistentDataContainer.class);when(e.getPersistentDataContainer()).thenReturn(pdc);when(pdc.has(com.customrpg.utils.ControlledUndead.OWNER,org.bukkit.persistence.PersistentDataType.STRING)).thenReturn(true);assertFalse(com.customrpg.balance.BalanceCombatListener.hostile(e));assertFalse(combat.enemy(player,e));var death=mock(EntityDeathEvent.class);when(death.getEntity()).thenReturn(e);when(death.getDrops()).thenReturn(new ArrayList<>());skills.death(death);verify(death).setDroppedExp(0);var load=new org.bukkit.event.world.EntitiesLoadEvent(mock(org.bukkit.Chunk.class),List.of(e));skills.load(load);verify(e).remove();}
    @Test void cancellingBeforeSacrificeDetonationCannotLeaveQueuedDamage(){var target=mob(0,.5);skills.cast(player,talent(NecroSkill.SUMMON),1);skills.cast(player,talent(NecroSkill.SACRIFICE),1);skills.quit(new PlayerQuitEvent(player,"test"));ticks(20);verify(target,never()).damage(anyDouble(),eq(player));assertEquals(0,alive());}
    @Test void ordinaryMobTauntHoldsForFortyTicksAndRestoresItsPreviousTarget(){var enemy=(Zombie)mob(0,2);var target=new AtomicReference<LivingEntity>(player);when(enemy.getTarget()).thenAnswer(x->target.get());doAnswer(x->{target.set(x.getArgument(0));return null;}).when(enemy).setTarget(any());skills.cast(player,talent(NecroSkill.SUMMON),1);skills.cast(player,talent(NecroSkill.COLOSSUS),1);var giant=bodies.get(2);assertSame(giant,target.get());var retarget=new EntityTargetLivingEntityEvent(enemy,player,EntityTargetEvent.TargetReason.CLOSEST_PLAYER);skills.target(retarget);assertSame(giant,retarget.getTarget());ticks(40);assertSame(player,target.get());}
    @Test void gateLineOfSightChecksDoNotSendAnyWaveThroughAWall(){var target=mob(0,6);skills.cast(player,talent(NecroSkill.GATE),1);when(world.rayTraceBlocks(any(Location.class),any(Vector.class),anyDouble(),any(),anyBoolean())).thenAnswer(x->{Location from=x.getArgument(0);return new org.bukkit.util.RayTraceResult(from.toVector().add(new Vector(0,0,1)),mock(Block.class),org.bukkit.block.BlockFace.NORTH);});ticks(70);verify(target,never()).damage(anyDouble(),eq(player));}
}
